"use client";

import React, { useState } from 'react';
import useSWR from 'swr';
import Link from 'next/link';
import { toast } from 'react-hot-toast';
import { Eye, Pencil, Trash2, Plus as PlusIcon, Users } from 'lucide-react';
import { apiClient } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { AdvancedTable, Column } from '@/components/ui/advanced-table';
import { withAuth } from '@/context/AuthContext';

interface Customer {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  address?: string;
  created_at: string;
}

// Define fetcher function
const fetcher = async (key: string): Promise<Customer[]> => {
  const response = await apiClient.customers.list({ page: 1, limit: 50 });
  return response.data || [];
};

function CustomersPage() {
  const { data, error, isLoading, mutate } = useSWR<Customer[]>(
    ["customers:list"],
    ([key]) => fetcher(String(key)),
    { 
      revalidateOnFocus: false,
      revalidateIfStale: false
    }
  );

  const customers = data || [];

  const handleDelete = async (id: string, name: string) => {
    if (!window.confirm(`Are you sure you want to delete customer "${name}"? This action cannot be undone.`)) {
      return;
    }

    try {
      await apiClient.customers.delete(id);
      toast.success('Customer deleted successfully');
      mutate();
    } catch (err: any) {
      const message = err?.response?.data?.message || err?.message || 'Failed to delete customer';
      toast.error(message);
    }
  };

  const columns: Column<Customer>[] = [
    {
      key: 'name',
      label: 'Customer',
      sortable: true,
      render: (value, customer) => (
        <div>
          <div className="font-medium">{customer.name}</div>
          <div className="text-sm text-muted-foreground">{customer.email}</div>
        </div>
      ),
    },
    {
      key: 'phone',
      label: 'Phone',
      sortable: true,
      render: (value) => value || 'N/A',
    },
    {
      key: 'address',
      label: 'Address',
      sortable: true,
      render: (value) => value || 'N/A',
    },
    {
      key: 'created_at',
      label: 'Created',
      sortable: true,
      render: (value) => new Date(value).toLocaleDateString(),
    },
  ];

  if (isLoading) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Customers</h1>
            <p className="text-muted-foreground">Manage your customers</p>
          </div>
          <Button asChild>
            <Link href="/customers/new">
              <PlusIcon className="w-4 h-4 mr-2" />
              Add Customer
            </Link>
          </Button>
        </div>
        <Card>
          <CardContent className="p-6">
            <div className="text-center">Loading customers...</div>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Customers</h1>
            <p className="text-muted-foreground">Manage your customers</p>
          </div>
          <Button asChild>
            <Link href="/customers/new">
              <PlusIcon className="w-4 h-4 mr-2" />
              Add Customer
            </Link>
          </Button>
        </div>
        <Card>
          <CardContent className="p-6">
            <div className="text-center text-red-500">Failed to load customers</div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Customers</h1>
          <p className="text-muted-foreground">Manage your customers</p>
        </div>
        <Button asChild>
          <Link href="/customers/new">
            <PlusIcon className="w-4 h-4 mr-2" />
            Add Customer
          </Link>
        </Button>
      </div>

      {customers.length === 0 ? (
        <Card>
          <CardContent className="p-12">
            <div className="text-center space-y-4">
              <Users className="w-12 h-12 text-muted-foreground mx-auto" />
              <div>
                <h3 className="text-lg font-semibold">No customers found</h3>
                <p className="text-muted-foreground">Start building your customer base by adding your first customer.</p>
              </div>
              <Button asChild>
                <Link href="/customers/new">
                  <PlusIcon className="w-4 h-4 mr-2" />
                  Add Customer
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>Customers ({customers.length})</CardTitle>
          </CardHeader>
          <CardContent>
            <AdvancedTable
              data={customers}
              columns={columns}
              searchable
              pagination
              pageSize={20}
              emptyMessage="No customers found"
            />
          </CardContent>
        </Card>
      )}
    </div>
  );
}

export default withAuth(CustomersPage);

