interface Supplier {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  address?: string;
  created_at: string;
}

// Define fetcher function
const fetcher = async (key: string): Promise<Supplier[]> => {
  const response = await apiClient.suppliers.list({ page: 1, limit: 50 });
  return response.data || [];
};

function SuppliersPage() {
  const { data, error, isLoading, mutate } = useSWR<Supplier[]>(
    ["suppliers:list"],
    ([key]) => fetcher(String(key)),
    { 
      revalidateOnFocus: false,
      revalidateIfStale: false
    }
  );

  const suppliers = data || [];

  const handleDelete = async (id: string, name: string) => {
    if (!window.confirm(`Are you sure you want to delete supplier "${name}"? This action cannot be undone.`)) {
      return;
    }

    try {
      await apiClient.suppliers.delete(id);
      toast.success('Supplier deleted successfully');
      mutate();
    } catch (err: any) {
      const message = err?.response?.data?.message || err?.message || 'Failed to delete supplier';
      toast.error(message);
    }
  };

  const columns: Column<Supplier>[] = [
    {
      key: 'name',
      label: 'Supplier',
      sortable: true,
      render: (value, supplier) => (
        <div>
          <div className="font-medium">{supplier.name}</div>
          <div className="text-sm text-muted-foreground">{supplier.email}</div>
        </div>
      ),
    },
    {
      key: 'phone',
      label: 'Phone',
      sortable: true,
      render: (value) => value || 'N/A',
    },
    {
      key: 'address',
      label: 'Address',
      sortable: true,
      render: (value) => value || 'N/A',
    },
    {
      key: 'created_at',
      label: 'Created',
      sortable: true,
      render: (value) => new Date(value).toLocaleDateString(),
    },
  ];

  if (isLoading) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Suppliers</h1>
            <p className="text-muted-foreground">Manage your suppliers</p>
          </div>
          <Button asChild>
            <Link href="/suppliers/new">
              <PlusIcon className="w-4 h-4 mr-2" />
              Add Supplier
            </Link>
          </Button>
        </div>
        <Card>
          <CardContent className="p-6">
            <div className="text-center">Loading suppliers...</div>
          </CardContent>
        </Card>
      </div>
    );
