  if (error) {
    return (
      <div className="space-y-6 p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Suppliers</h1>
            <p className="text-muted-foreground">Manage your suppliers</p>
          </div>
          <Button asChild>
            <Link href="/suppliers/new">
              <PlusIcon className="w-4 h-4 mr-2" />
              Add Supplier
            </Link>
          </Button>
        </div>
        <Card>
          <CardContent className="p-6">
            <div className="text-center text-red-500">Failed to load suppliers</div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Suppliers</h1>
          <p className="text-muted-foreground">Manage your suppliers</p>
        </div>
        <Button asChild>
          <Link href="/suppliers/new">
            <PlusIcon className="w-4 h-4 mr-2" />
            Add Supplier
          </Link>
        </Button>
      </div>

      {suppliers.length === 0 ? (
        <Card>
          <CardContent className="p-12">
            <div className="text-center space-y-4">
              <Truck className="w-12 h-12 text-muted-foreground mx-auto" />
              <div>
                <h3 className="text-lg font-semibold">No suppliers found</h3>
                <p className="text-muted-foreground">Build your supplier network by adding your first supplier.</p>
              </div>
              <Button asChild>
                <Link href="/suppliers/new">
                  <PlusIcon className="w-4 h-4 mr-2" />
                  Add Supplier
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>Suppliers ({suppliers.length})</CardTitle>
          </CardHeader>
          <CardContent>
            <AdvancedTable
              data={suppliers}
              columns={columns}
              searchable
              pagination
              pageSize={20}
              emptyMessage="No suppliers found"
            />
          </CardContent>
        </Card>
      )}
    </div>
  );
}

export default withAuth(SuppliersPage);

